from pathlib import Pathimport jsonimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltROOT = Path(__file__).resolve().parent.parentRAW = ROOT / 'data' / 'raw'PROCESSED = ROOT / 'data' / 'processed'RESULTS = ROOT / 'results'PROCESSED.mkdir(parents=True, exist_ok=True)RESULTS.mkdir(parents=True, exist_ok=True)SAMPLE_FILE = RAW / 'multisat_2024_recent_sample.csv'HISTORY_FILE = RAW / 'multisat_2024_recent_gp_history.json'KP_FILE = PROCESSED / 'kp_daily_2024-04-01_to_2024-06-30.csv'BANDS = ['200-350 km', '350-500 km', '500-650 km', '650-800 km']ANALYSIS_START = pd.Timestamp('2024-05-01', tz='UTC')ANALYSIS_END = pd.Timestamp('2024-05-22', tz='UTC')MU = 398600.4418  # km^3 / s^2R_EARTH = 6371.0  # km, approximation consistent with earlier scriptsdef main():    for f in (SAMPLE_FILE, HISTORY_FILE, KP_FILE):        if not f.exists():            raise FileNotFoundError(f'Missing {f}')    sample = pd.read_csv(SAMPLE_FILE)    sample['norad_id'] = pd.to_numeric(sample.norad_id, errors='coerce').astype('Int64')    sample = sample.dropna(subset=['norad_id']).drop_duplicates('norad_id')    sample['norad_id'] = sample.norad_id.astype(int)    sample['altitude_band'] = sample.altitude_band.astype(str)    history = pd.DataFrame(json.loads(HISTORY_FILE.read_text()))    required = ['NORAD_CAT_ID', 'EPOCH', 'MEAN_MOTION']    missing = set(required) - set(history.columns)    if missing:        raise RuntimeError(f'Missing fields in GP history: {sorted(missing)}')    history['norad_id'] = pd.to_numeric(history['NORAD_CAT_ID'], errors='coerce')    history['epoch'] = pd.to_datetime(history['EPOCH'], errors='coerce', utc=True)    history['mean_motion'] = pd.to_numeric(history['MEAN_MOTION'], errors='coerce')    history = history.dropna(subset=['norad_id', 'epoch', 'mean_motion']).copy()    history = history[history.mean_motion > 0].copy()    history['norad_id'] = history.norad_id.astype(int)    n = history.mean_motion * (2.0 * np.pi / 86400)    history['altitude_km'] = (MU / n**2)**(1/3) - R_EARTH    history['date'] = history.epoch.dt.floor('D')    # One value per UTC day. No interpolation and no forward-filling.    daily = (history.groupby(['norad_id', 'date'], as_index=False)             .agg(altitude_km=('altitude_km', 'median'), gp_records=('altitude_km', 'size'))             .sort_values(['norad_id', 'date']))    daily['previous_date'] = daily.groupby('norad_id').date.shift(1)    daily['previous_altitude_km'] = daily.groupby('norad_id').altitude_km.shift(1)    daily['gap_days'] = (daily.date - daily.previous_date).dt.total_seconds() / 86400    # Defined only when there are measurements on consecutive calendar days.    daily['decay_km_day'] = np.where(        daily.gap_days == 1.0,        daily.previous_altitude_km - daily.altitude_km,        np.nan)    daily = daily[(daily.date >= ANALYSIS_START) & (daily.date < ANALYSIS_END)].copy()    kp = pd.read_csv(KP_FILE)    if not {'date', 'daily_max_kp'}.issubset(kp.columns):        raise RuntimeError('Kp CSV must have date and daily_max_kp columns')    kp['date'] = pd.to_datetime(kp.date, errors='coerce', utc=True).dt.floor('D')    kp['daily_max_kp'] = pd.to_numeric(kp.daily_max_kp, errors='coerce')    kp = kp.dropna(subset=['date']).drop_duplicates('date')    daily = daily.merge(kp[['date', 'daily_max_kp']], on='date', how='left', validate='many_to_one')    daily = daily.merge(sample[['norad_id', 'satellite_name', 'launch_year', 'altitude_band', 'altitude_km']]                        .rename(columns={'altitude_km': 'sample_altitude_km'}),                        on='norad_id', how='inner', validate='many_to_one')    daily['storm_day'] = daily.daily_max_kp >= 5    # Retain all original values and make quality exclusions explicit.    daily['suspicious_change'] = (        (daily.decay_km_day < -0.10) | (daily.decay_km_day > 2.0))    daily['usable_decay'] = (daily.decay_km_day.notna() & daily.daily_max_kp.notna()                            & ~daily.suspicious_change)    daily.to_csv(PROCESSED / 'multisat_2024_recent_daily_decay_kp.csv', index=False)    coverage = (daily.groupby('norad_id', as_index=False)                .agg(daily_altitude_days=('altitude_km','size'),                     valid_consecutive_days=('decay_km_day','count'),                     usable_decay_days=('usable_decay','sum'),                     suspicious_days=('suspicious_change','sum'),                     storm_obs=('storm_day', lambda s: int(s.sum()))))    coverage = sample.merge(coverage, on='norad_id', how='left')    coverage.to_csv(RESULTS / 'multisat_2024_recent_coverage.csv', index=False)    usable = daily[daily.usable_decay].copy()    rows = []    for sid, group in usable.groupby('norad_id'):        s = group[group.storm_day]        q = group[~group.storm_day]        # A satellite requires at least 2 storm and 5 nonstorm daily observations.        if len(s) < 2 or len(q) < 5:            continue        r = np.nan        if group.daily_max_kp.nunique() > 1 and group.decay_km_day.nunique() > 1:            r = float(group[['daily_max_kp', 'decay_km_day']].corr().iloc[0, 1])        meta = group.iloc[0]        rows.append({            'norad_id': sid, 'satellite_name': meta.satellite_name,            'launch_year': meta.launch_year, 'altitude_band': meta.altitude_band,            'reference_altitude_km': float(group.altitude_km.median()),            'storm_days': len(s), 'nonstorm_days': len(q),            'mean_storm_decay_km_day': float(s.decay_km_day.mean()),            'mean_nonstorm_decay_km_day': float(q.decay_km_day.mean()),            'storm_minus_nonstorm_km_day': float(s.decay_km_day.mean()-q.decay_km_day.mean()),            'pearson_r': r,        })    summary = pd.DataFrame(rows)    if summary.empty:        print('No satellites have enough storm and nonstorm observations; review recent coverage CSV.')        return    summary.to_csv(RESULTS / 'multisat_2024_recent_satellite_summary.csv', index=False)    band = (summary.groupby('altitude_band', as_index=False)            .agg(satellites=('norad_id','nunique'),                 median_decay_difference_km_day=('storm_minus_nonstorm_km_day','median'),                 median_pearson_r=('pearson_r','median')))    band['altitude_band'] = pd.Categorical(band.altitude_band, categories=BANDS, ordered=True)    band = band.sort_values('altitude_band')    band.to_csv(RESULTS / 'multisat_2024_recent_band_summary.csv', index=False)    fig, ax = plt.subplots(figsize=(9, 5))    for b, g in summary.groupby('altitude_band'):        ax.scatter(g.reference_altitude_km, g.storm_minus_nonstorm_km_day,                   alpha=0.75, s=35, label=b)    ax.axhline(0, color='gray', ls='--', lw=1)    ax.set(xlabel='Median measured orbital altitude (km)',           ylabel='Storm − nonstorm daily decay (km/day)',           title='Recent-launch satellites: May 2024 Kp association')    ax.grid(alpha=0.25); ax.legend()    fig.tight_layout()    fig.savefig(RESULTS / 'multisat_2024_recent_storm_difference.png', dpi=220)    plt.close(fig)    groups = [summary.loc[summary.altitude_band == b, 'storm_minus_nonstorm_km_day'].values              for b in BANDS]    fig, ax = plt.subplots(figsize=(9, 5))    ax.boxplot(groups, labels=BANDS, showfliers=True)      ax.axhline(0, color='gray', ls='--', lw=1)    ax.set(xlabel='Altitude band', ylabel='Storm − nonstorm decay (km/day)',           title='Recent-launch satellites: May 2024 distributions')    ax.grid(axis='y', alpha=0.25)    fig.tight_layout()    fig.savefig(RESULTS / 'multisat_2024_recent_band_boxplot.png', dpi=220)    plt.close(fig)    print(f'Original selected objects: {len(sample)}')    print(f'Objects with daily altitude: {daily.norad_id.nunique()}')    print(f'With enough storm/nonstorm data: {len(summary)}')    print(f'Suspicious daily changes flagged: {int(daily.suspicious_change.sum())}')    print('\nAltitude band summaries (satellite-level medians):')    print(band.to_string(index=False, float_format=lambda x: f'{x:.6f}'))    print('\nSaved in results/: recent_coverage, recent_satellite_summary, recent_band_summary,')    print('recent_storm_difference.png, recent_band_boxplot.png')    print('Saved in data/processed/: multisat_2024_recent_daily_decay_kp.csv')    print('\nCaution: PAYLOAD and launch year do not confirm active operations;')    print('differences are observational, not causal storm effects.')if __name__ == '__main__':    main()